```bash
cd /home/vscode/nullness-benchmarks/libgdx && nl -ba gdx/src/com/badlogic/gdx/graphics/Texture.java | sed -n '320,420p' && cat <<'EOF' > /tmp/Texture_tail.java
  /**
   * Sets the {@link AssetManager}. When the context is lost, textures managed by the asset manager
   * are reloaded by the manager on a separate thread (provided that a suitable {@link AssetLoader}
   * is registered with the manager). Textures not managed by the AssetManager are reloaded via the
   * usual means on the rendering thread.
   *
   * @param manager the asset manager.
   */
  public static void setAssetManager(AssetManager manager) {
    Texture.assetManager = manager;
  }

  public static String getManagedStatus() {
    StringBuilder builder = new StringBuilder();
    builder.append("Managed textures/app: { ");
    for (Application app : managedTextures.keySet()) {
      builder.append(managedTextures.get(app).size);
      builder.append(" ");
    }
    builder.append("}");
    return builder.toString();
  }

  /**
   * @return the number of managed textures currently loaded
   */
  public static int getNumManagedTextures() {
    if (Gdx.app == null) return 0;
    Array<Texture> textures = managedTextures.get(Gdx.app);
    return textures == null ? 0 : textures.size;
  }
}
EOF
